/**
 * FreeLang v4 JIT — 공통 타입 정의
 */

// ============================================================
// Opcode (FreeLang v4 VM 기준)
// ============================================================

export type Opcode =
  | "CONST" | "ADD" | "SUB" | "MUL" | "DIV" | "MOD"
  | "EQ" | "NEQ" | "LT" | "LTE" | "GT" | "GTE"
  | "AND" | "OR" | "NOT" | "NEG"
  | "LOAD" | "STORE" | "LOAD_GLOBAL" | "STORE_GLOBAL"
  | "JUMP" | "JUMP_IF_FALSE" | "JUMP_IF_TRUE"
  | "CALL" | "RETURN" | "HALT"
  | "ARRAY_NEW" | "ARRAY_PUSH" | "ARRAY_GET" | "ARRAY_SET" | "ARRAY_LEN"
  | "PRINT" | "POP" | "DUP"
  | string;

// ============================================================
// 핫스팟 감지
// ============================================================

export const HOTSPOT_THRESHOLD = 100; // 테스트용 (프로덕션: 1000)
export const LOOP_HOTSPOT_THRESHOLD = 50;

export interface ExecutionCounter {
  fn:      string;  // 함수명
  pc:      number;  // 바이트코드 PC
  count:   number;  // 실행 횟수
  isHot:   boolean; // 핫스팟 여부
  isLoop:  boolean; // 루프 여부
}

export interface HotspotReport {
  hotFunctions: string[];   // 핫스팟 함수명 목록
  hotPcs:       number[];   // 핫스팟 PC 목록
  totalCalls:   number;     // 전체 호출 횟수
  hotRatio:     number;     // 핫스팟 비율 (0~1)
}

// ============================================================
// 네이티브 코드 (LLVM IR 시뮬레이션)
// ============================================================

export type ArchTarget = "x86_64" | "arm64" | "llvm_ir";

export interface NativeCode {
  fnName:    string;
  arch:      ArchTarget;
  ir:        string;         // LLVM IR 텍스트 or x86-64 어셈블리
  sizeBytes: number;
  optimized: boolean;
  optLevel:  0 | 1 | 2 | 3; // -O0 ~ -O3
}

// ============================================================
// 인라인 캐시 (IC)
// ============================================================

export type CacheState = "uninitialized" | "monomorphic" | "polymorphic" | "megamorphic";

export interface ICEntry {
  site:       string;  // 호출 사이트 식별자 ("fn:pc")
  state:      CacheState;
  typesSeen:  string[];  // 관찰된 타입들 ("i32", "f64", ...)
  hitCount:   number;
  missCount:  number;
  hitRate:    number;   // 0~1
}

// ============================================================
// PGO (Profile-Guided Optimization)
// ============================================================

export interface BranchProfile {
  pc:         number;
  trueCount:  number;
  falseCount: number;
  probability: number; // true 확률 (0~1)
  predictable: boolean; // >80% 이면 예측 가능
}

export interface LoopProfile {
  pc:         number;
  tripCount:  number;   // 총 반복 횟수
  execCount:  number;   // 루프 진입 횟수
  avgTrips:   number;   // 평균 반복 횟수
  isHot:      boolean;
}

export interface CallProfile {
  fnName:    string;
  callCount: number;
  avgArgs:   number;
  isRecursive: boolean;
}

export interface PgoProfile {
  branches: BranchProfile[];
  loops:    LoopProfile[];
  calls:    CallProfile[];
  strategy: "none" | "aggressive" | "conservative";
}

// ============================================================
// 역최적화 (Deoptimization)
// ============================================================

export type DeoptReason =
  | "type_mismatch"
  | "range_check_failed"
  | "null_check_failed"
  | "bounds_check_failed"
  | "overflow"
  | "assumption_violated";

export interface DeoptGuard {
  pc:         number;
  fnName:     string;
  reason:     DeoptReason;
  expected:   string;  // 기대 타입/값
  actual:     string;  // 실제 타입/값
  triggered:  boolean;
  count:      number;  // 트리거 횟수
}

export interface DeoptEvent {
  timestamp:  number;
  fnName:     string;
  pc:         number;
  reason:     DeoptReason;
  fallback:   "interpreted"; // 항상 인터프리터로 폴백
}

// ============================================================
// JIT 통계
// ============================================================

export interface JitStats {
  hotFunctions:     number;
  compiledFunctions: number;
  deoptCount:       number;
  icHitRate:        number;
  speedupEstimate:  number;  // 배율 (예: 2.5 = 2.5배 빠름)
  profileCoverage:  number;  // PGO 커버리지 (0~1)
}

