/**
 * FreeLang v4 JIT — Native Code Generator
 *
 * FreeLang v4 VM 바이트코드를 LLVM IR로 변환합니다.
 * (실제 JIT 실행은 LLVM 툴체인 필요; 여기서는 IR 텍스트 생성)
 *
 * 지원 변환:
 *   - i32/f64 산술 연산 → LLVM add/sub/mul/sdiv
 *   - 조건 분기 → LLVM br
 *   - 함수 호출 → LLVM call
 *   - 배열 접근 → LLVM getelementptr
 *
 * 최적화 레벨:
 *   O0: 변환만
 *   O1: 상수 폴딩
 *   O2: 데드 코드 제거 + 강도 감소
 *   O3: 루프 언롤링 (avgTrips <= 8)
 */

import { NativeCode, ArchTarget } from "./jit-types";

// ============================================================
// NativeCodeGen
// ============================================================

export interface CodegenInput {
  fnName:   string;
  params:   { name: string; type: "i32" | "f64" | "bool" | "str" }[];
  retType:  "i32" | "f64" | "bool" | "void";
  body:     CodegenOp[];  // 간소화 IR 연산
}

export interface CodegenOp {
  op:      string;
  args?:   (string | number)[];
  result?: string;
}

export class NativeCodeGen {
  // ── LLVM IR 생성 ──────────────────────────────────────────

  generate(
    input: CodegenInput,
    optLevel: 0 | 1 | 2 | 3 = 1,
    arch: ArchTarget = "llvm_ir"
  ): NativeCode {
    const ir = arch === "x86_64"
      ? this.genX86(input, optLevel)
      : this.genLlvmIr(input, optLevel);

    return {
      fnName:    input.fnName,
      arch,
      ir,
      sizeBytes: ir.length,
      optimized: optLevel > 0,
      optLevel,
    };
  }

  // ── LLVM IR 생성 ──────────────────────────────────────────

  private genLlvmIr(input: CodegenInput, optLevel: number): string {
    const lines: string[] = [];
    const llvmRet = this.toLlvmType(input.retType);
    const paramStr = input.params
      .map((p) => `${this.toLlvmType(p.type)} %${p.name}`)
      .join(", ");

    lines.push(`; FreeLang v4 JIT — LLVM IR (O${optLevel})`);
    lines.push(`; Function: ${input.fnName}`);
    lines.push(`define ${llvmRet} @${input.fnName}(${paramStr}) {`);
    lines.push(`entry:`);

    let regCount = 0;
    const newReg = () => `%r${regCount++}`;

    // O1+: 상수 폴딩 패스
    const ops = optLevel >= 1 ? this.constantFold(input.body) : input.body;

    // O2+: 데드 코드 제거
    const liveOps = optLevel >= 2 ? this.deadCodeElim(ops) : ops;

    for (const op of liveOps) {
      const reg = op.result ?? newReg();
      switch (op.op) {
        case "add_i32":
          lines.push(`  ${reg} = add i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "sub_i32":
          lines.push(`  ${reg} = sub i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "mul_i32":
          lines.push(`  ${reg} = mul i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "div_i32":
          lines.push(`  ${reg} = sdiv i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "add_f64":
          lines.push(`  ${reg} = fadd double ${op.args![0]}, ${op.args![1]}`);
          break;
        case "mul_f64":
          lines.push(`  ${reg} = fmul double ${op.args![0]}, ${op.args![1]}`);
          break;
        case "cmp_lt":
          lines.push(`  ${reg} = icmp slt i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "cmp_eq":
          lines.push(`  ${reg} = icmp eq i32 ${op.args![0]}, ${op.args![1]}`);
          break;
        case "br_cond":
          lines.push(`  br i1 ${op.args![0]}, label %${op.args![1]}, label %${op.args![2]}`);
          break;
        case "br":
          lines.push(`  br label %${op.args![0]}`);
          break;
        case "label":
          lines.push(`${op.args![0]}:`);
          break;
        case "const_i32":
          lines.push(`  ${reg} = add i32 0, ${op.args![0]}`); // 상수 폴딩 결과
          break;
        case "ret":
          lines.push(`  ret ${llvmRet} ${op.args![0]}`);
          break;
        case "call":
          lines.push(`  ${reg} = call ${llvmRet} @${op.args![0]}(${(op.args!.slice(1) as string[]).join(", ")})`);
          break;
        case "phi_i32": {
          const pairs = (op.args as string[])
            .join(", ");
          lines.push(`  ${reg} = phi i32 ${pairs}`);
          break;
        }
        case "alloca":
          lines.push(`  ${reg} = alloca i32`);
          break;
        case "store":
          lines.push(`  store i32 ${op.args![0]}, i32* ${op.args![1]}`);
          break;
        case "load":
          lines.push(`  ${reg} = load i32, i32* ${op.args![0]}`);
          break;
        // O3: 루프 언롤링 힌트
        case "loop_hint":
          if (optLevel >= 3) {
            lines.push(`  ; !{!"llvm.loop.unroll.count", i32 ${op.args![0]}}`);
          }
          break;
        default:
          lines.push(`  ; [unknown op: ${op.op}]`);
      }
    }

    // 암시적 void 리턴
    if (input.retType === "void") lines.push(`  ret void`);
    lines.push(`}`);

    return lines.join("\n");
  }

  // ── x86-64 어셈블리 생성 (간소화) ──────────────────────

  private genX86(input: CodegenInput, optLevel: number): string {
    const lines: string[] = [];
    lines.push(`; FreeLang v4 JIT — x86-64 (O${optLevel})`);
    lines.push(`${input.fnName}:`);
    lines.push(`  push rbp`);
    lines.push(`  mov rbp, rsp`);

    // 파라미터 → rdi, rsi, rdx, rcx (System V ABI)
    const regs = ["rdi", "rsi", "rdx", "rcx"];
    input.params.forEach((p, i) => {
      if (i < regs.length) {
        lines.push(`  ; param ${p.name} in ${regs[i]}`);
      }
    });

    const ops = optLevel >= 1 ? this.constantFold(input.body) : input.body;
    for (const op of ops) {
      switch (op.op) {
        case "add_i32":
          lines.push(`  add eax, ${op.args![1]}`);
          break;
        case "sub_i32":
          lines.push(`  sub eax, ${op.args![1]}`);
          break;
        case "mul_i32":
          lines.push(`  imul eax, ${op.args![1]}`);
          break;
        case "div_i32":
          lines.push(`  cdq`);
          lines.push(`  idiv ${op.args![1]}`);
          break;
        case "ret":
          lines.push(`  mov eax, ${op.args![0]}`);
          lines.push(`  pop rbp`);
          lines.push(`  ret`);
          break;
        default:
          lines.push(`  ; [${op.op}]`);
      }
    }

    lines.push(`  pop rbp`);
    lines.push(`  ret`);

    return lines.join("\n");
  }

  // ── 최적화 패스 ───────────────────────────────────────────

  /** O1: 상수 폴딩 — 상수끼리 연산은 컴파일 타임에 계산 */
  private constantFold(ops: CodegenOp[]): CodegenOp[] {
    return ops.map((op) => {
      if (!op.args) return op;
      const [a, b] = op.args as (string | number)[];
      const numA = typeof a === "number" ? a : (isNaN(Number(a)) ? null : Number(a));
      const numB = typeof b === "number" ? b : (isNaN(Number(b)) ? null : Number(b));

      if (numA !== null && numB !== null) {
        let folded: number | null = null;
        if (op.op === "add_i32") folded = numA + numB;
        if (op.op === "sub_i32") folded = numA - numB;
        if (op.op === "mul_i32") folded = numA * numB;
        if (op.op === "div_i32" && numB !== 0) folded = Math.trunc(numA / numB);

        if (folded !== null) {
          return { op: "const_i32", args: [folded], result: op.result };
        }
      }
      return op;
    });
  }

  /** O2: 데드 코드 제거 — result가 사용되지 않는 연산 제거 */
  private deadCodeElim(ops: CodegenOp[]): CodegenOp[] {
    // 사용된 result 목록 수집
    const used = new Set<string>();
    for (const op of ops) {
      if (op.args) {
        for (const arg of op.args) {
          if (typeof arg === "string" && arg.startsWith("%")) used.add(arg);
        }
      }
    }
    // ret의 인자는 항상 사용됨
    for (const op of ops) {
      if (op.op === "ret" && op.args) {
        for (const arg of op.args) {
          if (typeof arg === "string") used.add(arg);
        }
      }
    }

    return ops.filter((op) => {
      if (!op.result) return true; // result 없는 건 항상 유지 (br, store, ret 등)
      return used.has(op.result);
    });
  }

  // ── 헬퍼 ──────────────────────────────────────────────────

  private toLlvmType(t: string): string {
    switch (t) {
      case "i32":  return "i32";
      case "f64":  return "double";
      case "bool": return "i1";
      case "void": return "void";
      default:     return "i8*"; // str → 포인터
    }
  }
}

