     1→// Memory Allocator
     2→// Manages heap allocation and deallocation
     3→
     4→use std::collections::HashMap;
     5→use crate::core::Value;
     6→use std::time::Instant;
     7→
     8→/// Allocated block information
     9→#[derive(Debug, Clone)]
    10→struct AllocatedBlock {
    11→    value: Value,
    12→    size: usize,
    13→    allocated_at: Instant,
    14→    ref_count: usize,
    15→}
    16→
    17→/// Memory allocator with GC support
    18→pub struct MemoryAllocator {
    19→    heap: HashMap<u64, AllocatedBlock>,
    20→    next_id: u64,
    21→    total_allocated: usize,
    22→    total_freed: usize,
    23→    gc_threshold: usize,  // Trigger GC at 5MB
    24→    allocation_count: u64,
    25→}
    26→
    27→impl MemoryAllocator {
    28→    /// Create new allocator
    29→    pub fn new() -> Self {
    30→        MemoryAllocator {
    31→            heap: HashMap::new(),
    32→            next_id: 1,
    33→            total_allocated: 0,
    34→            total_freed: 0,
    35→            gc_threshold: 5 * 1024 * 1024,  // 5MB
    36→            allocation_count: 0,
    37→        }
    38→    }
    39→
    40→    /// Allocate value on heap
    41→    pub fn allocate(&mut self, value: Value) -> u64 {
    42→        let id = self.next_id;
    43→        self.next_id += 1;
    44→
    45→        let size = self.estimate_size(&value);
    46→        self.total_allocated += size;
