/**
 * FreeLang v4 JIT — JIT VM
 *
 * FreeLang v4 VM을 래핑하여 JIT 레이어를 추가합니다.
 *
 * 실행 흐름:
 *   1. 일반 VM으로 실행 (Tier-0: Interpreter)
 *   2. HotspotDetector가 핫스팟 감지
 *   3. PgoAnalyzer가 프로파일 수집
 *   4. InlineCache가 타입 정보 수집
 *   5. 핫 함수 → NativeCodeGen이 LLVM IR 생성 (Tier-1: JIT)
 *   6. Deoptimizer Guard 등록 → 타입 위반 시 Tier-0 폴백
 *
 * 메트릭:
 *   - JIT 컴파일된 함수 수
 *   - IC 히트율
 *   - 역최적화 횟수
 *   - 예상 속도 향상
 */

import { Lexer }    from "../../freelang-v4/src/lexer";
import { Parser }   from "../../freelang-v4/src/parser";
import { Compiler } from "../../freelang-v4/src/compiler";
import { VM }       from "../../freelang-v4/src/vm";

import { HotspotDetector }   from "./hotspot-detector";
import { InlineCache }       from "./inline-cache";
import { PgoAnalyzer }       from "./pgo-analyzer";
import { NativeCodeGen, CodegenInput } from "./native-codegen";
import { Deoptimizer }       from "./deoptimizer";
import { NativeCode, JitStats } from "./jit-types";

// ============================================================
// JIT VM 실행 결과
// ============================================================

export interface JitRunResult {
  output:   string[];
  error:    string | null;
  jitStats: JitStats;
  compiled: NativeCode[];    // 생성된 네이티브 코드
  warnings: string[];
}

// ============================================================
// JitVm
// ============================================================

export class JitVm {
  private hotspot   = new HotspotDetector(this.fnThreshold, this.loopThreshold);
  private ic        = new InlineCache();
  private pgo       = new PgoAnalyzer();
  private codegen   = new NativeCodeGen();
  private deopt     = new Deoptimizer();
  private compiled  = new Map<string, NativeCode>();

  constructor(
    private fnThreshold   = 100,
    private loopThreshold = 50
  ) {}

