// Escape Analysis
//
// 객체/변수가 할당된 스코프를 벗어나는지(escape) 분석합니다.
// 탈출하지 않는 객체는 힙 대신 스택에 할당 → GC 부담 제거.
//
// 탈출 케이스:
//   1. 함수 반환값으로 사용 (ReturnEscape)
//   2. 외부 클로저/함수에 전달 (CallEscape)
//   3. 전역 변수에 저장 (GlobalEscape)
//   4. 힙 할당 객체의 필드로 저장 (FieldEscape)

use std::collections::{HashMap, HashSet};

// ────────────────────────────────────────────────────────────────
// 탈출 이유
// ────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum EscapeReason {
    /// 함수 반환값
    ReturnEscape,
    /// 외부 함수 호출 인자
    CallEscape { callee: String },
    /// 전역 변수 저장
    GlobalEscape { var: String },
    /// 힙 객체의 필드로 저장
    FieldEscape { object: String, field: String },
}

// ────────────────────────────────────────────────────────────────
// 할당 위치
// ────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AllocationSite {
    /// 스택 할당 (GC 없음, 스코프 종료 시 자동 해제)
    Stack,
    /// 힙 할당 (GC 대상)
    Heap,
}

// ────────────────────────────────────────────────────────────────
// 변수 정보
// ────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub struct VarInfo {
    /// 변수 이름
    pub name: String,
    /// 정의된 스코프 깊이 (0 = 최상위)
    pub scope_depth: usize,
    /// 탈출 여부
    pub escapes: bool,
    /// 탈출 이유 목록
    pub escape_reasons: Vec<EscapeReason>,
    /// 권장 할당 위치
    pub alloc_site: AllocationSite,
    /// 참조 횟수
    pub ref_count: usize,
}

impl VarInfo {
    fn new(name: impl Into<String>, scope_depth: usize) -> Self {
        VarInfo {
            name: name.into(),
            scope_depth,
            escapes: false,
            escape_reasons: Vec::new(),
            alloc_site: AllocationSite::Stack,
            ref_count: 0,
        }
    }

    fn mark_escape(&mut self, reason: EscapeReason) {
        self.escapes = true;
        self.alloc_site = AllocationSite::Heap;
        if !self.escape_reasons.contains(&reason) {
            self.escape_reasons.push(reason);
        }
    }
}

// ────────────────────────────────────────────────────────────────
// IR 명령어 (FreeLang 바이트코드 추상화)
// ────────────────────────────────────────────────────────────────

#[derive(Debug, Clone)]
pub enum EscapeIr {
    /// 변수 정의: let x = ...
    Assign { var: String },
    /// 함수 반환: return x
    Return { var: String },
    /// 함수 호출에 인자 전달: f(x)
    Call { callee: String, args: Vec<String> },
    /// 전역 저장: GLOBAL_X = x
    StoreGlobal { global: String, var: String },
    /// 필드 저장: obj.field = x
    StoreField { object: String, field: String, var: String },
    /// 스코프 진입
    EnterScope,
    /// 스코프 종료
    ExitScope,
}

// ────────────────────────────────────────────────────────────────
// Escape Analysis 결과
// ────────────────────────────────────────────────────────────────

#[derive(Debug)]
pub struct EscapeAnalysisResult {
    /// 변수별 분석 결과
    pub vars: HashMap<String, VarInfo>,
    /// 스택 할당 가능 변수 수
    pub stack_alloc_count: usize,
    /// 힙 할당 필요 변수 수
    pub heap_alloc_count: usize,
    /// 절약된 GC 압력 (스택 할당 비율)
    pub gc_pressure_reduction: f64,
}

impl EscapeAnalysisResult {
    pub fn summary(&self) -> String {
        let total = self.stack_alloc_count + self.heap_alloc_count;
        format!(
            "EscapeAnalysis: 총 {} 변수 | 스택={} ({:.1}%) | 힙={} ({:.1}%) | GC 압력 감소={:.1}%",
            total,
            self.stack_alloc_count,
            if total > 0 { self.stack_alloc_count as f64 / total as f64 * 100.0 } else { 0.0 },
            self.heap_alloc_count,
            if total > 0 { self.heap_alloc_count as f64 / total as f64 * 100.0 } else { 0.0 },
            self.gc_pressure_reduction * 100.0,
        )
    }

    /// 스택 할당 권장 변수 목록
    pub fn stack_candidates(&self) -> Vec<&VarInfo> {
        let mut v: Vec<&VarInfo> = self.vars.values()
            .filter(|vi| vi.alloc_site == AllocationSite::Stack)
            .collect();
        v.sort_by(|a, b| a.name.cmp(&b.name));
        v
    }

    /// 힙 할당이 필요한 변수 목록
    pub fn heap_required(&self) -> Vec<&VarInfo> {
        let mut v: Vec<&VarInfo> = self.vars.values()
            .filter(|vi| vi.alloc_site == AllocationSite::Heap)
            .collect();
        v.sort_by(|a, b| a.name.cmp(&b.name));
        v
    }
}

// ────────────────────────────────────────────────────────────────
// EscapeAnalyzer
// ────────────────────────────────────────────────────────────────

pub struct EscapeAnalyzer {
    vars: HashMap<String, VarInfo>,
    scope_stack: Vec<HashSet<String>>,  // 스코프별 변수 집합
    current_depth: usize,
}

impl EscapeAnalyzer {
    pub fn new() -> Self {
        EscapeAnalyzer {
            vars: HashMap::new(),
            scope_stack: vec![HashSet::new()],
            current_depth: 0,
        }
    }

    // ── IR 명령어 처리 ────────────────────────────────────────

    pub fn process(&mut self, ir: &[EscapeIr]) {
        for instr in ir {
            match instr {
                EscapeIr::Assign { var } => self.on_assign(var),
                EscapeIr::Return { var } => self.on_return(var),
                EscapeIr::Call { callee, args } => self.on_call(callee, args),
                EscapeIr::StoreGlobal { global, var } => self.on_store_global(global, var),
                EscapeIr::StoreField { object, field, var } => {
                    self.on_store_field(object, field, var)
                }
                EscapeIr::EnterScope => self.push_scope(),
                EscapeIr::ExitScope => self.pop_scope(),
            }
        }
    }

    fn on_assign(&mut self, var: &str) {
        let info = VarInfo::new(var, self.current_depth);
        if let Some(scope) = self.scope_stack.last_mut() {
            scope.insert(var.to_string());
        }
        self.vars.insert(var.to_string(), info);
    }

    fn on_return(&mut self, var: &str) {
        if let Some(info) = self.vars.get_mut(var) {
            info.mark_escape(EscapeReason::ReturnEscape);
        }
    }

    fn on_call(&mut self, callee: &str, args: &[String]) {
        for arg in args {
            if let Some(info) = self.vars.get_mut(arg) {
                info.ref_count += 1;
                // 외부 호출에 전달 → 탈출
                info.mark_escape(EscapeReason::CallEscape {
                    callee: callee.to_string(),
                });
            }
        }
    }

    fn on_store_global(&mut self, global: &str, var: &str) {
        if let Some(info) = self.vars.get_mut(var) {
            info.mark_escape(EscapeReason::GlobalEscape {
                var: global.to_string(),
            });
        }
    }

    fn on_store_field(&mut self, object: &str, field: &str, var: &str) {
        if let Some(info) = self.vars.get_mut(var) {
            // object가 힙에 있으면 var도 힙으로 올라감
            let obj_escapes = self.vars.get(object).map(|o| o.escapes).unwrap_or(true);
            if obj_escapes {
                info.mark_escape(EscapeReason::FieldEscape {
                    object: object.to_string(),
                    field: field.to_string(),
                });
            }
        }
    }

    fn push_scope(&mut self) {
        self.current_depth += 1;
        self.scope_stack.push(HashSet::new());
    }

    fn pop_scope(&mut self) {
        // 스코프 종료 시 이 스코프의 비탈출 변수는 스택 해제
        if let Some(_scope) = self.scope_stack.pop() {
            // 스택 변수는 scope 종료와 함께 자동 해제 (GC 불필요)
        }
        if self.current_depth > 0 {
            self.current_depth -= 1;
        }
    }

    // ── 결과 생성 ─────────────────────────────────────────────

    pub fn analyze(mut self, ir: &[EscapeIr]) -> EscapeAnalysisResult {
        self.process(ir);

        // 연쇄 탈출 전파: A → B (A가 탈출하면 A를 담은 B도 탈출)
        self.propagate_escape();

        let stack_alloc_count = self.vars.values()
            .filter(|v| v.alloc_site == AllocationSite::Stack)
            .count();
        let heap_alloc_count = self.vars.values()
            .filter(|v| v.alloc_site == AllocationSite::Heap)
            .count();
        let total = stack_alloc_count + heap_alloc_count;
        let gc_pressure_reduction = if total > 0 {
            stack_alloc_count as f64 / total as f64
        } else {
            0.0
        };

        EscapeAnalysisResult {
            vars: self.vars,
            stack_alloc_count,
            heap_alloc_count,
            gc_pressure_reduction,
        }
    }

    /// 탈출 전파: FieldEscape에서 object → var 방향으로 재분석
    fn propagate_escape(&mut self) {
        // 간단한 1회 전파 (대부분의 경우 1패스로 충분)
        let escapees: Vec<String> = self.vars.values()
            .filter(|v| v.escapes)
            .map(|v| v.name.clone())
            .collect();

        for name in escapees {
            // FieldEscape에서 object가 이미 탈출 중이면 해당 object를 담는 모든 var도 전파
            let reasons: Vec<EscapeReason> = self.vars.get(&name)
                .map(|v| v.escape_reasons.clone())
                .unwrap_or_default();

            for reason in reasons {
                if let EscapeReason::FieldEscape { object, field } = reason {
                    if let Some(obj_info) = self.vars.get_mut(&object) {
                        obj_info.mark_escape(EscapeReason::FieldEscape {
                            object: name.clone(),
                            field,
                        });
                    }
                }
            }
        }
    }
}

impl Default for EscapeAnalyzer {
    fn default() -> Self {
        Self::new()
    }
}

// ────────────────────────────────────────────────────────────────
// 테스트
// ────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    fn run(ir: Vec<EscapeIr>) -> EscapeAnalysisResult {
        EscapeAnalyzer::new().analyze(&ir)
    }

    /// 단순 지역 변수 → 스택 할당
    #[test]
    fn test_local_var_stack() {
        let ir = vec![
            EscapeIr::Assign { var: "x".into() },
            EscapeIr::Assign { var: "y".into() },
        ];
        let result = run(ir);

        assert_eq!(result.stack_alloc_count, 2);
        assert_eq!(result.heap_alloc_count, 0);

        let x = result.vars.get("x").unwrap();
        assert!(!x.escapes);
        assert_eq!(x.alloc_site, AllocationSite::Stack);
    }

    /// 반환값 → 힙 할당
    #[test]
    fn test_return_escape() {
        let ir = vec![
            EscapeIr::Assign { var: "result".into() },
            EscapeIr::Return { var: "result".into() },
        ];
        let result = run(ir);

        let info = result.vars.get("result").unwrap();
        assert!(info.escapes);
        assert_eq!(info.alloc_site, AllocationSite::Heap);
        assert!(info.escape_reasons.contains(&EscapeReason::ReturnEscape));
        assert_eq!(result.heap_alloc_count, 1);
    }

    /// 외부 함수 호출 → 힙 할당
    #[test]
    fn test_call_escape() {
        let ir = vec![
            EscapeIr::Assign { var: "buf".into() },
            EscapeIr::Call {
                callee: "write_file".into(),
                args: vec!["buf".into()],
            },
        ];
        let result = run(ir);

        let info = result.vars.get("buf").unwrap();
        assert!(info.escapes);
        assert_eq!(info.alloc_site, AllocationSite::Heap);
        assert!(info.escape_reasons.contains(&EscapeReason::CallEscape {
            callee: "write_file".into()
        }));
    }

    /// 전역 저장 → 힙 할당
    #[test]
    fn test_global_escape() {
        let ir = vec![
            EscapeIr::Assign { var: "cfg".into() },
            EscapeIr::StoreGlobal {
                global: "GLOBAL_CFG".into(),
                var: "cfg".into(),
            },
        ];
        let result = run(ir);

        let info = result.vars.get("cfg").unwrap();
        assert!(info.escapes);
        assert!(info.escape_reasons.contains(&EscapeReason::GlobalEscape {
            var: "GLOBAL_CFG".into()
        }));
    }

    /// 힙 객체 필드 저장 → 힙 할당
    #[test]
    fn test_field_escape() {
        let ir = vec![
            EscapeIr::Assign { var: "node".into() },
            EscapeIr::Assign { var: "child".into() },
            EscapeIr::Return { var: "node".into() },  // node가 탈출
            EscapeIr::StoreField {
                object: "node".into(),
                field: "left".into(),
                var: "child".into(),
            },
        ];
        let result = run(ir);

        let child = result.vars.get("child").unwrap();
        assert!(child.escapes, "child는 탈출한 node의 필드 → 힙 필요");
    }

    /// 스코프 분리 — 내부 스코프 변수는 스택
    #[test]
    fn test_scope_isolation() {
        let ir = vec![
            EscapeIr::Assign { var: "outer".into() },
            EscapeIr::EnterScope,
            EscapeIr::Assign { var: "inner".into() },
            EscapeIr::ExitScope,
        ];
        let result = run(ir);

        let outer = result.vars.get("outer").unwrap();
        let inner = result.vars.get("inner").unwrap();
        assert!(!outer.escapes);
        assert!(!inner.escapes);
        assert_eq!(outer.scope_depth, 0);
        assert_eq!(inner.scope_depth, 1);
    }

    /// 혼합 시나리오 — GC 압력 감소 측정
    #[test]
    fn test_gc_pressure_reduction() {
        let ir = vec![
            EscapeIr::Assign { var: "a".into() },         // 스택
            EscapeIr::Assign { var: "b".into() },         // 스택
            EscapeIr::Assign { var: "c".into() },         // 힙 (반환)
            EscapeIr::Return { var: "c".into() },
            EscapeIr::Assign { var: "d".into() },         // 스택
        ];
        let result = run(ir);

        assert_eq!(result.stack_alloc_count, 3);
        assert_eq!(result.heap_alloc_count, 1);
        // 75% 스택 → GC 압력 75% 감소
        assert!((result.gc_pressure_reduction - 0.75).abs() < 1e-9);
    }

    /// summary() 포맷 확인
    #[test]
    fn test_summary_format() {
        let ir = vec![
            EscapeIr::Assign { var: "x".into() },
            EscapeIr::Return { var: "x".into() },
        ];
        let result = run(ir);
        let s = result.summary();
        assert!(s.contains("EscapeAnalysis"));
        assert!(s.contains("힙=1"));
        assert!(s.contains("스택=0"));
    }

    /// 미정의 변수에 탈출 적용해도 패닉 없음
    #[test]
    fn test_undefined_var_safe() {
        let ir = vec![
            EscapeIr::Return { var: "undefined_var".into() },
        ];
        let result = run(ir);
        // 변수 정보 없으면 그냥 무시
        assert_eq!(result.vars.len(), 0);
    }

    /// ref_count 추적
    #[test]
    fn test_ref_count() {
        let ir = vec![
            EscapeIr::Assign { var: "buf".into() },
            EscapeIr::Call { callee: "fn1".into(), args: vec!["buf".into()] },
            EscapeIr::Call { callee: "fn2".into(), args: vec!["buf".into()] },
        ];
        let result = run(ir);
        let buf = result.vars.get("buf").unwrap();
        assert_eq!(buf.ref_count, 2);
    }
}

