/**
 * FreeLang v4 JIT — Escape Analysis 최적화 패스
 *
 * 목적:
 *   JIT 컴파일 전에 함수 IR을 분석하여 탈출하지 않는 변수를
 *   스택 할당으로 교체 → 힙 할당 횟수 감소 → GC 압력 감소.
 *
 * JitVm과의 통합 흐름:
 *   Interpreter → HotspotDetector → [EscapeAnalyzer] → NativeCodeGen
 *                                        ↑
 *                    alloca(stack) / malloc(heap) 결정
 *
 * 탈출 판별 기준:
 *   ReturnEscape  — return 문에 사용됨
 *   CallEscape    — 외부 함수의 인자로 전달됨
 *   GlobalEscape  — 전역 변수에 저장됨
 *   FieldEscape   — 이미 탈출한 객체의 필드에 저장됨
 *   ClosureEscape — 클로저 캡처됨
 */

import { CodegenOp } from "./native-codegen";

// ──────────────────────────────────────────────────────────────
// 탈출 이유
// ──────────────────────────────────────────────────────────────

export type EscapeReason =
  | { kind: "return" }
  | { kind: "call"; callee: string }
  | { kind: "global"; name: string }
  | { kind: "field"; object: string; field: string }
  | { kind: "closure"; fnName: string };

// ──────────────────────────────────────────────────────────────
// 할당 위치
// ──────────────────────────────────────────────────────────────

export type AllocSite = "stack" | "heap";

// ──────────────────────────────────────────────────────────────
// 변수 분석 결과
// ──────────────────────────────────────────────────────────────

export interface VarEscapeInfo {
  name:       string;
  escapes:    boolean;
  reasons:    EscapeReason[];
  allocSite:  AllocSite;
  scopeDepth: number;
  refCount:   number;
}

// ──────────────────────────────────────────────────────────────
// EscapeAnalysis 전체 결과
// ──────────────────────────────────────────────────────────────

export interface EscapeAnalysisResult {
  fnName:             string;
  vars:               Map<string, VarEscapeInfo>;
  stackCount:         number;
  heapCount:          number;
  /** GC 압력 감소 비율 (0~1) — 스택 변수 비율 */
  gcPressureReduction: number;
  /** NativeCodeGen 패치: alloca → heap_alloc 교체 목록 */
  stackCandidates:    string[];
  heapRequired:       string[];
}

export function summarize(r: EscapeAnalysisResult): string {
  const total = r.stackCount + r.heapCount;
  const stackPct = total > 0 ? (r.stackCount / total * 100).toFixed(1) : "0.0";
  const heapPct  = total > 0 ? (r.heapCount  / total * 100).toFixed(1) : "0.0";
  return (
    `EscapeAnalysis [${r.fnName}]: 총 ${total}변수 ` +
    `| 스택=${r.stackCount}(${stackPct}%) ` +
    `| 힙=${r.heapCount}(${heapPct}%) ` +
    `| GC압력감소=${(r.gcPressureReduction * 100).toFixed(1)}%`
  );
}

// ──────────────────────────────────────────────────────────────
// IR 명령어 (FreeLang v4 바이트코드 추상 표현)
// ──────────────────────────────────────────────────────────────

export type EscapeIr =
  | { op: "assign";       var: string }
  | { op: "return";       var: string }
  | { op: "call";         callee: string; args: string[] }
  | { op: "store_global"; global: string; var: string }
  | { op: "store_field";  object: string; field: string; var: string }
  | { op: "capture";      fnName: string; var: string }
  | { op: "enter_scope" }
  | { op: "exit_scope" };

// ──────────────────────────────────────────────────────────────
// EscapeAnalyzer
// ──────────────────────────────────────────────────────────────

export class EscapeAnalyzer {
  private vars        = new Map<string, VarEscapeInfo>();
  private scopeStack: Set<string>[] = [new Set()];
  private depth       = 0;

  constructor(private readonly fnName: string) {}

  // ── IR 처리 ───────────────────────────────────────────────

  process(ir: EscapeIr[]): this {
    for (const instr of ir) {
      switch (instr.op) {
        case "assign":       this.onAssign(instr.var);                         break;
        case "return":       this.onReturn(instr.var);                         break;
        case "call":         this.onCall(instr.callee, instr.args);            break;
        case "store_global": this.onStoreGlobal(instr.global, instr.var);     break;
        case "store_field":  this.onStoreField(instr.object, instr.field, instr.var); break;
        case "capture":      this.onCapture(instr.fnName, instr.var);         break;
        case "enter_scope":  this.pushScope();                                 break;
        case "exit_scope":   this.popScope();                                  break;
      }
    }
    return this;
  }

  private onAssign(varName: string): void {
    if (!this.vars.has(varName)) {
      this.vars.set(varName, {
        name: varName, escapes: false, reasons: [],
        allocSite: "stack", scopeDepth: this.depth, refCount: 0,
      });
    }
    this.scopeStack[this.scopeStack.length - 1].add(varName);
  }

  private onReturn(varName: string): void {
    const info = this.vars.get(varName);
    if (info) this.markEscape(info, { kind: "return" });
  }

  private onCall(callee: string, args: string[]): void {
    for (const arg of args) {
      const info = this.vars.get(arg);
      if (info) {
        info.refCount++;
        this.markEscape(info, { kind: "call", callee });
      }
    }
  }

  private onStoreGlobal(global: string, varName: string): void {
    const info = this.vars.get(varName);
    if (info) this.markEscape(info, { kind: "global", name: global });
  }

  private onStoreField(object: string, field: string, varName: string): void {
    const info     = this.vars.get(varName);
    const objInfo  = this.vars.get(object);
    // object가 이미 탈출 → var도 탈출
    if (info && (objInfo?.escapes ?? true)) {
      this.markEscape(info, { kind: "field", object, field });
    }
  }

  private onCapture(fnName: string, varName: string): void {
    const info = this.vars.get(varName);
    if (info) this.markEscape(info, { kind: "closure", fnName });
  }

  private pushScope(): void {
    this.depth++;
    this.scopeStack.push(new Set());
  }

  private popScope(): void {
    this.scopeStack.pop();
    if (this.depth > 0) this.depth--;
  }

  private markEscape(info: VarEscapeInfo, reason: EscapeReason): void {
    info.escapes   = true;
    info.allocSite = "heap";
    // 중복 이유 방지
    const dup = info.reasons.some((r) => JSON.stringify(r) === JSON.stringify(reason));
    if (!dup) info.reasons.push(reason);
  }

  // ── 연쇄 탈출 전파 ────────────────────────────────────────

  private propagate(): void {
    // FieldEscape: object가 탈출하면 object를 담는 외부 var도 탈출
    for (const [, info] of this.vars) {
      if (!info.escapes) continue;
      for (const r of info.reasons) {
        if (r.kind === "field") {
          const objInfo = this.vars.get(r.object);
          if (objInfo && !objInfo.escapes) {
            this.markEscape(objInfo, { kind: "field", object: info.name, field: r.field });
          }
        }
      }
    }
  }

  // ── 결과 생성 ─────────────────────────────────────────────

  analyze(ir: EscapeIr[]): EscapeAnalysisResult {
    this.process(ir);
    this.propagate();

    let stackCount = 0;
    let heapCount  = 0;
    const stackCandidates: string[] = [];
    const heapRequired:    string[] = [];

    for (const [name, info] of this.vars) {
      if (info.allocSite === "stack") { stackCount++; stackCandidates.push(name); }
      else                            { heapCount++;  heapRequired.push(name);    }
    }

    const total = stackCount + heapCount;
    return {
      fnName: this.fnName,
      vars:   this.vars,
      stackCount,
      heapCount,
      gcPressureReduction: total > 0 ? stackCount / total : 0,
      stackCandidates: stackCandidates.sort(),
      heapRequired:    heapRequired.sort(),
    };
  }
}

// ──────────────────────────────────────────────────────────────
// NativeCodeGen 패치 헬퍼
// alloca → heap_alloc 교체 (스택 후보가 아닌 경우)
// ──────────────────────────────────────────────────────────────

/**
 * CodegenOp 목록에서 alloca 명령어를 escape 결과에 따라 교체.
 * - 스택 후보: alloca 유지
 * - 힙 필요:   alloca → heap_alloc
 */
export function patchAllocations(
  ops: CodegenOp[],
  result: EscapeAnalysisResult
): CodegenOp[] {
  const stackSet = new Set(result.stackCandidates);

  return ops.map((op) => {
    if (op.op !== "alloca") return op;

    const varName = op.result ?? "";
    if (stackSet.has(varName)) {
      // 스택 — 그대로 유지 (코드젠: alloca i32)
      return op;
    } else {
      // 힙 — heap_alloc으로 교체 (실제 malloc 호출)
      return { op: "heap_alloc", result: op.result };
    }
  });
}

// ──────────────────────────────────────────────────────────────
// 테스트 (Jest / Bun 호환)
// ──────────────────────────────────────────────────────────────

if (require.main === module) {
  runTests();
}

function runTests(): void {
  let pass = 0;
  let fail = 0;

  function test(name: string, fn: () => void): void {
    try {
      fn();
      console.log(`  ✅ ${name}`);
      pass++;
    } catch (e: any) {
      console.log(`  ❌ ${name}: ${e.message}`);
      fail++;
    }
  }

  function assert(cond: boolean, msg: string): void {
    if (!cond) throw new Error(msg);
  }

  console.log("\n=== EscapeAnalyzer 테스트 ===\n");

  // ── 1. 지역 변수 → 스택
  test("지역 변수는 스택 할당", () => {
    const r = new EscapeAnalyzer("fn_local").analyze([
      { op: "assign", var: "x" },
      { op: "assign", var: "y" },
    ]);
    assert(r.stackCount === 2, `stackCount=${r.stackCount}`);
    assert(r.heapCount === 0,  `heapCount=${r.heapCount}`);
    assert(!r.vars.get("x")!.escapes, "x should not escape");
  });

  // ── 2. return → 힙
  test("반환값은 힙 할당", () => {
    const r = new EscapeAnalyzer("fn_ret").analyze([
      { op: "assign", var: "result" },
      { op: "return", var: "result" },
    ]);
    const info = r.vars.get("result")!;
    assert(info.escapes, "result should escape");
    assert(info.allocSite === "heap", "allocSite=heap");
    assert(info.reasons[0].kind === "return", "reason=return");
    assert(r.heapCount === 1, "heapCount=1");
  });

  // ── 3. 함수 호출 인자 → 힙
  test("외부 함수 인자는 힙 할당", () => {
    const r = new EscapeAnalyzer("fn_call").analyze([
      { op: "assign", var: "buf" },
      { op: "call", callee: "write_file", args: ["buf"] },
    ]);
    const info = r.vars.get("buf")!;
    assert(info.escapes, "buf escapes");
    assert(info.reasons[0].kind === "call", "reason=call");
    assert((info.reasons[0] as any).callee === "write_file", "callee=write_file");
  });

  // ── 4. 전역 저장 → 힙
  test("전역 저장은 힙 할당", () => {
    const r = new EscapeAnalyzer("fn_global").analyze([
      { op: "assign", var: "cfg" },
      { op: "store_global", global: "GLOBAL_CFG", var: "cfg" },
    ]);
    const info = r.vars.get("cfg")!;
    assert(info.escapes, "cfg escapes");
    assert(info.reasons[0].kind === "global", "reason=global");
  });

  // ── 5. 클로저 캡처 → 힙
  test("클로저 캡처 변수는 힙 할당", () => {
    const r = new EscapeAnalyzer("fn_closure").analyze([
      { op: "assign", var: "counter" },
      { op: "capture", fnName: "inner_fn", var: "counter" },
    ]);
    const info = r.vars.get("counter")!;
    assert(info.escapes, "counter escapes");
    assert(info.reasons[0].kind === "closure", "reason=closure");
  });

  // ── 6. 필드 저장 (탈출 객체) → 힙
  test("탈출 객체의 필드 → 힙 전파", () => {
    const r = new EscapeAnalyzer("fn_field").analyze([
      { op: "assign", var: "node" },
      { op: "assign", var: "child" },
      { op: "return", var: "node" },           // node 탈출
      { op: "store_field", object: "node", field: "left", var: "child" },
    ]);
    const child = r.vars.get("child")!;
    assert(child.escapes, "child escapes via field");
  });

  // ── 7. 스코프 깊이 추적
  test("스코프 깊이 추적", () => {
    const r = new EscapeAnalyzer("fn_scope").analyze([
      { op: "assign", var: "outer" },
      { op: "enter_scope" },
      { op: "assign", var: "inner" },
      { op: "exit_scope" },
    ]);
    assert(r.vars.get("outer")!.scopeDepth === 0, "outer depth=0");
    assert(r.vars.get("inner")!.scopeDepth === 1, "inner depth=1");
  });

  // ── 8. GC 압력 감소 측정
  test("GC 압력 감소 75%", () => {
    const r = new EscapeAnalyzer("fn_pressure").analyze([
      { op: "assign", var: "a" },
      { op: "assign", var: "b" },
      { op: "assign", var: "c" },
      { op: "assign", var: "d" },
      { op: "return", var: "d" },   // d만 탈출
    ]);
    assert(r.stackCount === 3, `stackCount=${r.stackCount}`);
    assert(r.heapCount === 1,  `heapCount=${r.heapCount}`);
    assert(Math.abs(r.gcPressureReduction - 0.75) < 1e-9, "gcReduction=0.75");
  });

  // ── 9. ref_count 추적
  test("ref_count 복수 호출 추적", () => {
    const r = new EscapeAnalyzer("fn_refcount").analyze([
      { op: "assign", var: "buf" },
      { op: "call", callee: "fn1", args: ["buf"] },
      { op: "call", callee: "fn2", args: ["buf"] },
    ]);
    assert(r.vars.get("buf")!.refCount === 2, "refCount=2");
  });

  // ── 10. patchAllocations
  test("patchAllocations: alloca → heap_alloc 교체", () => {
    const r = new EscapeAnalyzer("fn_patch").analyze([
      { op: "assign", var: "x" },          // 스택
      { op: "assign", var: "y" },          // 힙
      { op: "return", var: "y" },
    ]);
    const ops: CodegenOp[] = [
      { op: "alloca", result: "x" },
      { op: "alloca", result: "y" },
      { op: "add_i32", args: ["x", "1"], result: "%r0" },
    ];
    const patched = patchAllocations(ops, r);
    assert(patched[0].op === "alloca",     "x는 alloca 유지");
    assert(patched[1].op === "heap_alloc", "y는 heap_alloc 교체");
    assert(patched[2].op === "add_i32",    "다른 op는 그대로");
  });

  // ── 11. summarize 포맷
  test("summarize() 포맷 확인", () => {
    const r = new EscapeAnalyzer("fn_sum").analyze([
      { op: "assign", var: "x" },
      { op: "return", var: "x" },
    ]);
    const s = summarize(r);
    assert(s.includes("EscapeAnalysis"), "contains EscapeAnalysis");
    assert(s.includes("fn_sum"),         "contains fnName");
    assert(s.includes("힙=1"),           "contains 힙=1");
  });

  // ── 12. 미정의 변수 안전성
  test("미정의 변수 참조 안전", () => {
    const r = new EscapeAnalyzer("fn_safe").analyze([
      { op: "return", var: "ghost" },       // 정의 없음
      { op: "call", callee: "f", args: ["phantom"] },
    ]);
    // 패닉 없이 결과 반환
    assert(r.vars.size === 0, "정의된 변수 없음");
  });

  console.log(`\n결과: ${pass}/${pass + fail} 통과`);
  if (fail > 0) process.exit(1);
}
